create extension if not exists pgcrypto;
create table public.branches(id uuid primary key default gen_random_uuid(),name text not null,address text,is_active boolean not null default true,created_at timestamptz default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text default '',role text not null default 'staff' check(role in('admin','manager','finance','inventory','sales','support')),branch_id uuid references public.branches(id),is_active boolean not null default true);
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique);
create table public.products(id uuid primary key default gen_random_uuid(),sku text unique,barcode text,name text not null,description text,category_id uuid references public.categories(id),unit text default 'piece',pack_size text,cost_price numeric(14,2) default 0 check(cost_price>=0),retail_price numeric(14,2) default 0 check(retail_price>=0),wholesale_price numeric(14,2) default 0 check(wholesale_price>=0),reorder_level numeric(14,3) default 0,is_alcoholic boolean default false,minimum_age smallint,is_active boolean default true,created_at timestamptz default now());
create table public.inventory(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),branch_id uuid not null references public.branches(id),quantity numeric(14,3) not null default 0,unique(product_id,branch_id));
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),branch_id uuid not null references public.branches(id),movement_type text not null check(movement_type in('receipt','sale','adjustment','transfer_in','transfer_out','return','damage')),quantity numeric(14,3) not null check(quantity>0),reference text,reason text,created_by uuid references auth.users(id),created_at timestamptz default now());
create table public.customers(id uuid primary key default gen_random_uuid(),name text not null,phone text,email text,customer_type text default 'retail' check(customer_type in('retail','wholesale')),business_name text,tax_reference text,delivery_address text,age_verified_at timestamptz,is_active boolean default true,created_at timestamptz default now());
create table public.suppliers(id uuid primary key default gen_random_uuid(),name text not null,contact_name text,phone text,email text,address text,tax_reference text,payment_terms text,is_active boolean default true);
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text not null unique,customer_id uuid references public.customers(id),branch_id uuid references public.branches(id),order_type text default 'retail' check(order_type in('retail','wholesale')),status text default 'pending' check(status in('pending','confirmed','processing','ready','dispatched','completed','cancelled')),subtotal numeric(14,2) default 0,discount numeric(14,2) default 0,tax_amount numeric(14,2) default 0,total numeric(14,2) default 0,currency text default 'UGX' check(currency='UGX'),delivery_address text,age_check_passed boolean default false,created_at timestamptz default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid not null references public.products(id),quantity numeric(14,3) not null check(quantity>0),unit_price numeric(14,2) not null,discount numeric(14,2) default 0,tax_amount numeric(14,2) default 0,line_total numeric(14,2) not null);
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id),reference text unique,provider text,method text not null check(method in('cash','mobile_money','bank','card','other')),amount numeric(14,2) not null check(amount>0),currency text default 'UGX' check(currency='UGX'),status text default 'pending' check(status in('pending','successful','failed','refunded')),paid_at timestamptz);
create table public.expenses(id uuid primary key default gen_random_uuid(),branch_id uuid references public.branches(id),category text not null,description text not null,amount numeric(14,2) not null check(amount>0),tax_amount numeric(14,2) default 0,expense_date date default current_date,recorded_by uuid references auth.users(id));
create table public.purchase_orders(id uuid primary key default gen_random_uuid(),purchase_number text not null unique,supplier_id uuid not null references public.suppliers(id),branch_id uuid references public.branches(id),status text default 'draft',total numeric(14,2) default 0,expected_at date);
create table public.support_tickets(id uuid primary key default gen_random_uuid(),ticket_number text not null unique,customer_id uuid references public.customers(id),subject text not null,message text not null,priority text default 'normal',status text default 'open',assigned_to uuid references auth.users(id),created_at timestamptz default now(),resolved_at timestamptz);
create table public.documents(id uuid primary key default gen_random_uuid(),document_number text not null unique,document_type text not null,order_id uuid references public.orders(id),storage_path text,issued_by uuid references auth.users(id),issued_at timestamptz default now(),verification_code text unique default encode(gen_random_bytes(12),'hex'),status text default 'issued');
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id uuid,details jsonb default '{}'::jsonb,created_at timestamptz default now());
create table public.business_settings(key text primary key,value jsonb not null,updated_by uuid references auth.users(id),updated_at timestamptz default now());
create or replace function public.staff_role() returns text language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() and is_active=true limit 1 $$;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select public.staff_role() in('admin','manager','finance','inventory','sales','support') $$;
create or replace function public.is_manager() returns boolean language sql stable security definer set search_path=public as $$ select public.staff_role() in('admin','manager') $$;
do $$ declare t text; begin foreach t in array array['branches','profiles','categories','products','inventory','inventory_movements','customers','suppliers','orders','order_items','payments','expenses','purchase_orders','support_tickets','documents','audit_logs','business_settings'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "public categories read" on public.categories for select using(true);
create policy "public active products read" on public.products for select using(is_active=true);
create policy "staff branches read" on public.branches for select to authenticated using(public.is_staff());
create policy "staff profiles read" on public.profiles for select to authenticated using(id=auth.uid() or public.is_manager());
create policy "admin profiles manage" on public.profiles for all to authenticated using(public.staff_role()='admin') with check(public.staff_role()='admin');
create policy "managers categories manage" on public.categories for all to authenticated using(public.is_manager()) with check(public.is_manager());
create policy "staff products manage" on public.products for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff inventory manage" on public.inventory for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff movements manage" on public.inventory_movements for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff customers manage" on public.customers for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff suppliers manage" on public.suppliers for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff orders manage" on public.orders for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff order items manage" on public.order_items for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "finance payments manage" on public.payments for all to authenticated using(public.staff_role() in('admin','manager','finance')) with check(public.staff_role() in('admin','manager','finance'));
create policy "finance expenses manage" on public.expenses for all to authenticated using(public.staff_role() in('admin','manager','finance')) with check(public.staff_role() in('admin','manager','finance'));
create policy "staff purchase orders manage" on public.purchase_orders for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff tickets manage" on public.support_tickets for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff documents manage" on public.documents for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "admin audit read" on public.audit_logs for select to authenticated using(public.staff_role()='admin');
create policy "staff audit insert" on public.audit_logs for insert to authenticated with check(public.is_staff() and actor_id=auth.uid());
create policy "staff settings read" on public.business_settings for select to authenticated using(public.is_staff());
create policy "admin settings manage" on public.business_settings for all to authenticated using(public.staff_role()='admin') with check(public.staff_role()='admin');
insert into public.categories(name,slug) values('Water','water'),('Juices & Mixers','juices-mixers'),('Soft Drinks','soft-drinks'),('Energy Drinks','energy-drinks'),('Tea & Coffee','tea-coffee'),('Beer, Wine & Spirits','beer-wine-spirits') on conflict(slug) do nothing;
